/**
 * A window too large to cut. `regionTooLarge` and the name are what JBrowse
 * and @jbrowse/bandage-core read a zoom-in notice by; `fitsBp` is about how
 * wide a window would fit. `zoomHelps` is false where no narrower window
 * fits. Over a byte budget, `bytes` is what the window's read would fetch,
 * the byte budget that would load it.
 */
export class RegionTooLargeError extends Error {
    constructor(message, limit, windowBp, fitsBp, overBytes) {
        super(message);
        this.regionTooLarge = true;
        this.name = 'NodeLimitError';
        this.limit = limit;
        this.windowBp = windowBp;
        this.fitsBp = fitsBp;
        this.zoomHelps = overBytes === undefined || overBytes.zoomHelps === true;
        if (overBytes) {
            this.bytes = overBytes.bytes;
        }
    }
}
const SEP = '#';
// `grape#1#chr1` -> `grape`
export function panSNSample(refName) {
    return refName.split(SEP)[0];
}
// `grape#1#chr1` and `grape#chr1` -> `chr1`
export function panSNContig(refName) {
    const parts = refName.split(SEP);
    return parts.length >= 3
        ? parts.slice(2).join(SEP)
        : parts.length === 2
            ? parts[1]
            : refName;
}
export function panSNHaplotype(refName) {
    const parts = refName.split(SEP);
    return parts.length >= 3 ? `${parts[0]}${SEP}${parts[1]}` : undefined;
}
export function panSNMatchesPrefix(refName, prefix) {
    return (prefix !== undefined &&
        (refName === prefix || refName.startsWith(prefix + SEP)));
}
const precise = (n) => Number.parseFloat(n.toPrecision(3));
// `1.5Kbp`, `12Mbp`, `850bp`, as JBrowse writes a span
export function bpString(bp) {
    const mb = precise(bp / 1000000);
    return mb >= 1
        ? `${mb.toLocaleString('en-US')}Mbp`
        : bp >= 1000
            ? `${precise(bp / 1000).toLocaleString('en-US')}Kbp`
            : `${Math.floor(bp)}bp`;
}
